typedef unsigned char u_char;
typedef unsigned short u_short;
typedef unsigned int u_int;
typedef unsigned long u_long;

extern "C" char* strncpy(char*, const char*, u_int);
extern "C" char* strlwr(char*);

class nglFixedString
{
public:
  typedef u_long fint;
  enum { FINT_SIZE = 8, STR_SIZE = 32, NUM_FINTS = STR_SIZE / FINT_SIZE };
  typedef nglFixedString FS;

  fint* value() { return reinterpret_cast<fint*>(str); }
  const fint* value() const { return reinterpret_cast<const fint*>(str); }

  nglFixedString(const char* s)
  {
    for (int i = 0; i < NUM_FINTS; ++i)
      value()[i] = 0;
    strncpy(str, s, STR_SIZE - 1);
    strlwr(str);
  }

  const FS& operator=(const FS& rhs)
  {
    for (int i = 0; i < NUM_FINTS; ++i)
      value()[i] = rhs.value()[i];
    return *this;
  }

  char str[STR_SIZE];
};

struct nglTexture
{
  u_int TexStreamPos[2];
  u_short Width, Height;
  u_int Hash;
  u_char Type;
  u_char TW, TH;
  struct
  {
    u_int LoadedInPlace : 1;
    u_int Locked : 1;
    u_int VRAMOnly : 1;
    u_int System : 1;
    u_int RenderTarget : 1;
  } Flags;
  void* ph;
  u_int Format;
  u_int* Data;
  u_int NFrames;
  nglTexture** Frames;
  u_int SrcDataSize;
  u_int FileBuf[4];
  nglFixedString FileName;
};

class nglInstanceBank
{
public:
  void* Insert(const nglFixedString& Key, void* Value);
};

enum { NGLTF_32BIT = 0x1 };

extern nglTexture* nglCreateTexture(u_int Format, u_int Width, u_int Height);
extern nglTexture* nglWhiteTex;
extern nglInstanceBank nglTextureBank;

#define NGL_WHITE_TEXSIZE 32
#define NGL_RGBA32_TEX(r, g, b, a) ((int)(r)) | (((int)(g)) << 8) | (((int)(b)) << 16) | (((int)((a) + 1) >> 1) << 24)

void nglInitWhiteTexture()
{
  nglWhiteTex = nglCreateTexture(NGLTF_32BIT, NGL_WHITE_TEXSIZE, NGL_WHITE_TEXSIZE);
  nglWhiteTex->FileName = nglFixedString("nglwhite");
  nglWhiteTex->Flags.System = 1;

  u_int* Data = (u_int*)nglWhiteTex->Data;
  for (int j = 0; j < NGL_WHITE_TEXSIZE; j++)
    for (int i = 0; i < NGL_WHITE_TEXSIZE; i++)
      Data[j * NGL_WHITE_TEXSIZE + i] = NGL_RGBA32_TEX(0xFF, 0xFF, 0xFF, 0xFF);

  nglTextureBank.Insert(nglWhiteTex->FileName, nglWhiteTex);
}
